// Hol dir das bestehende Map-Objekt aus flow context (oder lege neu an)
let tableMap = flow.get('tableMap') || {};

// d = empfangene Daten
const d = msg.payload.data;

// Baue den Eintrag – speichere Modul weiter als Zahl!
tableMap[d.id] = {
    id:          d.id,
    timestamp:   d.timestamp,
    module:      d.module,  // bleibt als Zahl gespeichert
    mac:         d.mac,
    consumption: d.current_consumption,
    generation:  d.current_generation,
    storage:     d.current_storage,
    x:           d.coordinates.x,
    y:           d.coordinates.y,
    error:       d.error
};

// Speichere zurück ins context
flow.set('tableMap', tableMap);

// Mapping Zahl → Name (für Anzeige)
const MODULES = {
  0:  'Master',
  1:  'Solar',
  2:  'Wind',
  3:  'Wasserkraft',
  4:  'Elektrolyseur',
  5:  'Akku',
  6:  'Wasserstoff',
  7:  'Pumpspeicher',
  8:  'Haus',
  9:  'Fabrik',
  10: 'Auto',
  11: 'Umspannwerk'
};

// Für Tabelle: Array erzeugen und Modulnummern ersetzen
msg.payload = Object.values(tableMap).map(row => {
    return {
        ...row,
        module: MODULES[row.module] || ("Modul " + row.module)
    };
});

return msg;

// 1) ID & numeric Type-Index aus dem Flow-Context holen
const id   = flow.get('selectedId');
const type = flow.get('selectedType'); // 0,1,2 ODER evtl. schon ein String

if (id === undefined || id === null || type === undefined || type === null) {
  node.error(`selectedId (${id}) oder selectedType (${type}) fehlt im Context`);
  return null;
}

// 2) Alle Arrays holen
const all = flow.get('sliderArrays') || {};
const dev = all[id] || {};

// 3) Typ-Key robust ermitteln (Index -> Name, Name -> Name)
const TYPE_NAMES = ['Verbrauch','Erzeugung','Speicher'];
const typeName =
  (typeof type === 'number' && Number.isFinite(type) ? TYPE_NAMES[type] : null) ||
  (typeof type === 'string' ? type : null);

// 4) 24er-Array finden: erst nach Namen, dann (Fallback) nach numerischem Key
let arr = null;
if (typeName && Array.isArray(dev[typeName]) && dev[typeName].length === 24) {
  arr = dev[typeName];
} else if (typeof type === 'number' && Array.isArray(dev[type]) && dev[type].length === 24) {
  // falls jemand unter numerischem Key gespeichert hat
  arr = dev[type];
}

let anchorPoints = [];
if (Array.isArray(arr) && arr.length === 24) {
  anchorPoints = arr.map(v => Number(v) || 0);
} else {
  const foundLen =
    typeName && Array.isArray(dev[typeName]) ? dev[typeName].length :
    (typeof type === 'number' && Array.isArray(dev[type]) ? dev[type].length : 0);
  node.warn(`Kein gültiges 24h-Array für ID=${id}, TypeKey='${typeName ?? type}' gefunden (gefunden ${foundLen})`);
  anchorPoints = Array(24).fill(0);
}

// 5) MAC aus Context
let mac = flow.get('selectedMac');
if (!mac) {
  node.warn("Keine selectedMac im Context – verwende FF:FF:FF:FF:FF:FF");
  mac = "FF:FF:FF:FF:FF:FF";
}

// 6) Zyklus-Dauer & Interpolations-Punkte
let cycleDuration = flow.get('cycleDuration');
if (typeof cycleDuration !== 'number') { node.warn("No cycleDuration – default 3600"); cycleDuration = 3600; }
let interpPoints = flow.get('interpPoints');
if (typeof interpPoints !== 'number') { node.warn("No interpPoints – default 10"); interpPoints = 10; }

// 7) JSON bauen – type als NUMMER senden (falls String, auf Index mappen)
const typeIndex = (typeof type === 'number' && Number.isFinite(type))
  ? type
  : Math.max(0, TYPE_NAMES.indexOf(typeName));

const out = {
  cmd:                  "modify_mode",
  id:                   id,
  mac:                  mac,
  type:                 typeIndex,
  n_anchor_points:      anchorPoints.length,
  cycle_duration:       cycleDuration,
  interpolation_points: interpPoints,
  anchor_points:        anchorPoints
};

msg.payload = out;
node.warn("Built JSON: " + JSON.stringify(out));
return msg;

// msg.payload kann enthalten: { hour, value, id, type, season, preset }
// -> preset = zuletzt angewendeter Presetname ('Custom' bei manuell)

const p = msg.payload || {};
const { hour, value, id, type, season, preset } = p;

let all = flow.get('sliderArrays') || {};
let lastPresetMap = flow.get('lastPresetMap') || {}; // Struktur: { [id]: { [type]: { preset, season, ts } } }

// --- A) Preset/Season merken, wenn Info vorhanden ---
if (Number.isFinite(id) && typeof type === 'string' && typeof season === 'string' && typeof preset === 'string') {
  if (!lastPresetMap[id]) lastPresetMap[id] = {};
  lastPresetMap[id][type] = {
    preset,         // z.B. 'PV-Hochsommer' oder 'Custom'
    season,         // z.B. 'Sommer'
    ts: Date.now()  // optional
  };
  flow.set('lastPresetMap', lastPresetMap);
}

// --- B) Einzelwert speichern (klassisch) ---
if (Number.isFinite(id) && typeof type === 'string' && Number.isFinite(hour)) {
  if (!all[id]) all[id] = {};
  if (!Array.isArray(all[id][type]) || all[id][type].length !== 24) {
    all[id][type] = Array(24).fill(0);
  }
  all[id][type][hour] = Number(value) || 0;

  flow.set('sliderArrays', all);

  node.status({
    fill: 'blue',
    shape: 'dot',
    text: `ID ${id}, ${type}, ${hour} Uhr = ${value} (${preset || '—'})`
  });
}

// keine Weitergabe
return null;

// Function: Save selected cycle duration

// 1. Aus dem Payload kommt die gewünschte Zyklusdauer (in Sekunden o.ä.)
const cycleDuration = parseInt(msg.payload, 10);

// 2. Ab in den Flow‑Context
flow.set('cycleDuration', cycleDuration);

// 3. Status‑Anzeige am Node (optional)
node.status({
  fill: "blue",
  shape: "dot",
  text: `Cycle-Duration: ${cycleDuration}`
});

// 4. Nachricht weiterreichen (oder return null, wenn Du hier nichts weiter anschließen willst)
return msg;

// Function: Save selected interpolation points

// 1. Lese den übergebenen Wert (z.B. aus einem Numeric‑Input)
//    Hier gehen wir davon aus, dass msg.payload schon eine Zahl oder String-Zahl ist:
const interpPoints = parseInt(msg.payload, 10);

// 2. Im Flow‑Context ablegen
flow.set('interpPoints', interpPoints);

// 3. Statusanzeige nur mit aktueller Einstellung
node.status({
  fill: "green",
  shape: "dot",
  text: `Interp‑Points: ${interpPoints}`
});

// 4. Nachricht weitergeben (oder return null, wenn nicht benötigt)
return msg;

// Init-Function (vor ui_template-Node ausführen)

const tableMap = flow.get('tableMap') || {};
const allArrays = flow.get('sliderArrays') || {};
const lastKey = flow.get('lastInitKey') || '';
const lastSelId = flow.get('lastSelectedId');
const lastPresetMap = flow.get('lastPresetMap') || {}; // { [id]: { [type]: { preset, season, ts } } }

const MODULES = {
  0: 'Master', 1: 'Solar', 2: 'Wind', 3: 'Wasserkraft', 4: 'Elektrolyseur',
  5: 'Batterie', 6: 'Wasserstoff', 7: 'Pumpspeicher', 8: 'Haus', 9: 'Fabrik',
  10: 'Auto', 11: 'Umspannwerk'
};

function getAvailableIds(map) {
  return Object.keys(map).map(Number).filter(Number.isFinite).sort((a, b) => a - b);
}
function buildIdModuleMap(map) {
  const out = {};
  for (const [k, v] of Object.entries(map)) {
    const id = Number(k);
    const mod = Number(v && v.module);
    if (!Number.isFinite(id) || !Number.isFinite(mod)) continue;
    if (!out[mod]) out[mod] = [];
    out[mod].push(id);
  }
  Object.keys(out).forEach(m => out[m].sort((a, b) => a - b));
  return out;
}
function pickMostRecentId(map, ids) {
  if (!ids || !ids.length) return null;
  return ids.slice().sort((a, b) => ((map[b]?.timestamp || 0) - (map[a]?.timestamp || 0)))[0];
}

if (msg.payload && msg.payload.init === true) {
  const availableIds = getAvailableIds(tableMap);
  const idModuleMap = buildIdModuleMap(tableMap);

  let reqModule = Number.isFinite(msg.payload.module) ? msg.payload.module : null;
  const idFromMsg  = Number.isFinite(msg.payload.id) ? msg.payload.id : null;
  const idFromLast = Number.isFinite(lastSelId) ? lastSelId : null;
  const recentId   = pickMostRecentId(tableMap, availableIds);

  if (reqModule == null && idFromMsg  != null && Number.isFinite(tableMap[idFromMsg ]?.module)) reqModule = tableMap[idFromMsg ].module;
  if (reqModule == null && idFromLast != null && Number.isFinite(tableMap[idFromLast]?.module)) reqModule = tableMap[idFromLast].module;
  if (reqModule == null && recentId   != null && Number.isFinite(tableMap[recentId  ]?.module)) reqModule = tableMap[recentId  ].module;
  if (reqModule == null) {
    const modCodes = Object.keys(idModuleMap).map(Number).filter(Number.isFinite).sort((a, b) => a - b);
    reqModule = modCodes.length ? modCodes[0] : null;
  }

  const moduleIds = (reqModule != null && Array.isArray(idModuleMap[reqModule])) ? idModuleMap[reqModule].slice() : availableIds.slice();

  let id = null;
  if (idFromMsg  != null && moduleIds.includes(idFromMsg )) id = idFromMsg;
  else if (idFromLast != null && moduleIds.includes(idFromLast)) id = idFromLast;
  else id = pickMostRecentId(tableMap, moduleIds);

  const reqType   = (typeof msg.payload.type   === 'string' && msg.payload.type)   || 'Verbrauch';
  const reqSeason = (typeof msg.payload.season === 'string' && msg.payload.season) || 'Frühling';
  const reqPreset = (typeof msg.payload.preset === 'string' && msg.payload.preset) || null;

  const remembered = (Number.isFinite(id) && lastPresetMap[id] && lastPresetMap[id][reqType])
    ? lastPresetMap[id][reqType]
    : null;

  const selectedPreset = reqPreset || (remembered?.preset || 'Custom');
  const selectedSeason = reqPreset ? reqSeason : (remembered?.season || reqSeason);

  // 24er-Array laden (oder Nullen)
  let arr = Array(24).fill(0);
  if (Number.isFinite(id) && allArrays[id] && Array.isArray(allArrays[id][reqType]) && allArrays[id][reqType].length === 24) {
    arr = allArrays[id][reqType];
  }

  // >>> ID & MAC im Context ablegen
  if (Number.isFinite(id)) {
    const thisKey = `${id}-${reqType}`;
    if (thisKey !== lastKey) flow.set('lastInitKey', thisKey);
    flow.set('lastSelectedId', id);
    flow.set('selectedId', id);
  }
  const mac = (Number.isFinite(id) && tableMap[id] && tableMap[id].mac) ? tableMap[id].mac : null;
  flow.set('selectedMac', mac);

  const moduleName = (reqModule != null && MODULES.hasOwnProperty(reqModule)) ? MODULES[reqModule] : (reqModule == null ? null : `Modul ${reqModule}`);

  msg.payload = {
    sliderValues: arr,
    availableIds,
    idModuleMap,

    selectedModuleCode: reqModule,
    selectedModuleName: moduleName || '',
    selectedId: Number.isFinite(id) ? id : null,
    selectedType: reqType,
    selectedSeason,
    selectedPreset,

    // >>> MAC ans UI (optional, aber hilfreich)
    selectedMac: mac
  };

  node.status({ fill: "green", shape: "dot", text: `Init Modul=${moduleName ?? '-'} ID=${id ?? '—'} MAC=${mac ?? '—'} Type=${reqType} Preset=${selectedPreset}` });
  return msg;
}

if (msg.payload && msg.payload.init) {
  node.warn(`Init request malformed: ${JSON.stringify(msg.payload)}`);
}
return null;

// Multi-Series in EINER Nachricht (Series=key: 'series'; X=key: 'x'; Y=key: 'y')

const typeFromMsg = (msg.payload && typeof msg.payload.type === 'string') ? msg.payload.type : null;
const type = typeFromMsg || flow.get('selectedType') || 'Verbrauch';

const all = flow.get('sliderArrays') || {};

// IDs mit gültigem 24er-Array für den Typ
const ids = Object.keys(all)
  .map(k => Number(k))
  .filter(id => Number.isFinite(id) && all[id] && Array.isArray(all[id][type]) && all[id][type].length === 24)
  .sort((a,b) => a - b);

// Summe berechnen
const summed = Array(24).fill(0);
ids.forEach(id => {
  const arr = all[id][type];
  for (let h = 0; h < 24; h++) summed[h] += Number(arr[h]) || 0;
});

// Punkte bauen: erst Summe, dann jede ID
const points = [];
for (let h = 0; h < 24; h++) {
  points.push({ series: 'Summe', x: h, y: summed[h] });
}
ids.forEach(id => {
  const arr = all[id][type];
  for (let h = 0; h < 24; h++) {
    points.push({ series: `ID ${id}`, x: h, y: Number(arr[h]) || 0 });
  }
});

// an Chart senden (+ optionale Achsentitel)
msg.payload = points;
msg.ui_control = {
  options: {
    parsing: { xAxisKey: 'x', yAxisKey: 'y' },
    scales: {
      x: {
        type: 'linear',
        min: 0, max: 23,
        title: { display: true, text: 'Stunde' },
        ticks: { stepSize: 1 }
      },
      y: {
        beginAtZero: true,
        title: { display: true, text: type }
      }
    },
    plugins: { legend: { display: true } }
  }
};

return msg;

// Function "Save Selection" – mappt type → Zahl (0/1)
const { init, id, type } = msg.payload;
if (init) {
  // ID wie gehabt speichern
  if (id) flow.set('selectedId', id);

  // Type als Zahl speichern: 0=Verbrauch, 1=Erzeugung
  const typeMap = {
    'Verbrauch': 0,
    'Erzeugung': 1
  };
  if (type in typeMap) {
    flow.set('selectedType', typeMap[type]);
  } else {
    node.warn(`Unbekannter type «${type}» – selectedType nicht gesetzt`);
  }
}
return msg;

// Function “Build Season-Specific Presets Query (msg.topic only)”
const { init, type, season } = msg.payload;

// 1) Nur auf Init reagieren
if (!init) {
  return null;
}

// 2) Validierung
if (typeof type !== 'string' || !type || typeof season !== 'string' || !season) {
  node.error(`Ungültiger type oder season: type=${type}, season=${season}`);
  return null;
}

// 3) SQL komplett in msg.topic (Achtung: einfache String-Escapes für Quotes)
msg.topic = `
  SELECT name, data
    FROM presets
   WHERE type   = '${type.replace(/'/g, "''")}'
     AND season = '${season.replace(/'/g, "''")}'
   ORDER BY name;
`;

return msg;

// Function "Basic Parse Presets"
const rows = Array.isArray(msg.payload) ? msg.payload : [];
const presets = {};
rows.forEach(r => {
  try {
    presets[r.name] = JSON.parse(r.data);
  } catch (e) {
    node.warn(`Invalid JSON for preset ${r.name}: ${e}`);
  }
});
msg.payload = { presets };
return msg;

// Netto-Chart (Erzeugung − Verbrauch) als Multi-Series in EINER Nachricht
// ui_chart: Series = key:'series', X = key:'x', Y = key:'y', X-Axis = Linear

const all = flow.get('sliderArrays') || {};
const ids = Object.keys(all).map(Number).filter(Number.isFinite).sort((a,b)=>a-b);

const zero24 = () => Array(24).fill(0);

const sumNet = Array(24).fill(0);
const points = [];

// Netto je ID: Erzeugung - Verbrauch
ids.forEach(id => {
  const gen  = (all[id] && Array.isArray(all[id]['Erzeugung']) && all[id]['Erzeugung'].length === 24) ? all[id]['Erzeugung']  : zero24();
  const cons = (all[id] && Array.isArray(all[id]['Verbrauch']) && all[id]['Verbrauch'].length === 24) ? all[id]['Verbrauch'] : zero24();

  let anyNonZero = false;
  const net = Array(24);
  for (let h = 0; h < 24; h++) {
    const v = (Number(gen[h]) || 0) - (Number(cons[h]) || 0);
    net[h] = v;
    sumNet[h] += v;
    if (v !== 0) anyNonZero = true;
  }

  if (anyNonZero) {
    for (let h = 0; h < 24; h++) {
      points.push({ series: `ID ${id} Netto`, x: h, y: net[h] });
    }
  }
});

// Summe Netto zuerst hinzufügen
for (let h = 0; h < 24; h++) {
  points.unshift({ series: 'Summe Netto', x: 23 - h, y: sumNet[23 - h] });
}

msg.payload = points;

msg.ui_control = {
  options: {
    parsing: { xAxisKey: 'x', yAxisKey: 'y' },
    scales: {
      x: {
        type: 'linear',
        min: 0, max: 23,
        title: { display: true, text: 'Stunde' },
        ticks: { stepSize: 1 }
      },
      y: {
        beginAtZero: false, // Netto kann negativ sein
        title: { display: true, text: 'Netto (Erzeugung − Verbrauch)' }
      }
    },
    plugins: { legend: { display: true } }
  }
};

return msg;

// Beispiel-Parameter (anpassen!)
const grid = {
  lat0: 51.333105,      // Ursprung Breitengrad
  lon0: 12.366167,      // Ursprung Längengrad
  metersPerUnit: 100,   // 1 Grid-Einheit = 100 m
  rotDeg: 0             // Drehung in Grad (0 = x nach Osten, y nach Norden)
};
flow.set('grid', grid);
node.status({fill:'green',shape:'dot',text:'Grid params gesetzt'});
return null;

// === Worldmap: tableMap -> Marker (Name = Modulname + ID), Icons, sauberes Umbenennen ===
const USE_AUTO_GRID = true; // false = grid muss existieren

// --- Grid laden/ggf. setzen ---
let grid = flow.get('grid');
if (!grid) {
  if (!USE_AUTO_GRID) { node.error('flow.grid nicht gesetzt'); return null; }
  grid = { lat0: 51.333105, lon0: 12.366167, metersPerUnit: 100, rotDeg: 0 };
  flow.set('grid', grid);
}
const { lat0, lon0, metersPerUnit, rotDeg } = grid;
const theta = (Number(rotDeg) || 0) * Math.PI / 180;

// --- Daten laden ---
const tableMap = flow.get('tableMap') || {};
const ids = Object.keys(tableMap).map(Number).filter(Number.isFinite).sort((a,b)=>a-b);

// --- Modulnamen & Icon-Zuordnung ---
const MODULES = {
  0:'Master', 1:'Solar', 2:'Wind', 3:'Wasserkraft', 4:'Elektrolyseur',
  5:'Batterie', 6:'Wasserstoff', 7:'Pumpspeicher', 8:'Haus', 9:'Fabrik', 10:'Auto', 11:'Umspannwerk'
};
function iconForModule(m){
  switch (Number(m)) {
    case 1:  return "/user-icons/solar-panels-green.svg";
    case 2:  return "/user-icons/wind-turbin-green.svg";
    case 3:  return "/user-icons/hydro-power.svg"
    case 4:  return "/user-icons/elektrolyseur.svg"
    case 5:  return "/user-icons/battery.svg"
    case 6:  return "/user-icons/wasserstoff.svg"
    case 7:  return "/user-icons/reservoir-blau.svg";
    case 8:  return "/user-icons/home-red.svg";
    case 9:  return "/user-icons/factory-red.svg";
    case 10: return "/user-icons/car-red.svg";
    default: return "/user-icons/default.svg"; // Fallback
  }
}
function layerForModule(m){
  switch (Number(m)) {
    case 1: case 2: case 3:  case 4: return 'Erzeuger';
    case 5: case 6: case 7:  return 'Speicher';
    case 8: case 9: case 10: return 'Verbraucher';
    default:                  return 'Erzeuger';
  }
}
function gridToLatLon(x, y){
  const ex = Number(x) * Number(metersPerUnit || 1);
  const ny = Number(y) * Number(metersPerUnit || 1);
  const east  = ex * Math.cos(theta) - ny * Math.sin(theta);
  const north = ex * Math.sin(theta) + ny * Math.cos(theta);
  const degLatPerM = 1/111320;
  const degLonPerM = 1/(111320 * Math.cos((Number(lat0)||0)*Math.PI/180));
  return { lat: Number(lat0) + north*degLatPerM, lon: Number(lon0) + east*degLonPerM };
}

// --- Letzten gesendeten Marker-Zustand STABIL PRO ID merken ---
const lastMetaById = flow.get('worldmap_lastMetaById') || {}; // { [id]: { name, layer } }

let sent = 0;
for (const id of ids) {
  const e = tableMap[id];
  if (!e) continue;

  const mcode = Number(e.module);
  const mname = MODULES[mcode] || `Modul ${mcode}`;
  const newName  = `${mname} ${id}`;          // gewünschter Anzeigename
  const newLayer = layerForModule(mcode);

  const prev = lastMetaById[id];              // <- stabil pro ID
  const nameChanged  = !prev || prev.name  !== newName;
  const layerChanged = !prev || prev.layer !== newLayer;

  // alten Marker löschen, wenn Name oder Layer sich ändern
  if (prev && (nameChanged || layerChanged)) {
    node.send({ payload: { name: prev.name, layer: prev.layer, deleted: true } });
  }

  // neuen/aktualisierten Marker senden
  const { lat, lon } = gridToLatLon(e.x || 0, e.y || 0);
  const popup = `${mname} (ID ${id})<br>MAC: ${e.mac || '-'}`;

  node.send({
    payload: {
      name: newName,
      lat, lon,
      layer: newLayer,
      popup,
      icon: iconForModule(mcode),
      iconSize: 45 // ggf. anpassen/je Modul variieren
      // ttl: 60 // optional: Marker verfällt nach 60s
    }
  });

  // Zustand aktualisieren
  lastMetaById[id] = { name: newName, layer: newLayer };
  sent++;
}

// speichern & Status
flow.set('worldmap_lastMetaById', lastMetaById);
node.status({ fill: sent ? 'green' : 'grey', shape: 'dot', text: sent ? `Worldmap: ${sent} Update(s)` : 'Worldmap: keine Änderungen' });
return null;

// Init-Function (vor ui_template-Node ausführen)

const tableMap      = flow.get('tableMap')      || {};
const allArrays     = flow.get('sliderArrays')  || {};
const lastKey       = flow.get('lastInitKey')   || '';
const lastSelId     = flow.get('lastSelectedId');
const lastPresetMap = flow.get('lastPresetMap') || {}; 
// { [id]: { [type]: { preset, season, ts } } }

const MODULES = {
  0: 'Master',
  1: 'Solar',
  2: 'Wind',
  3: 'Wasserkraft',
  4: 'Elektrolyseur',
  5: 'Batterie',
  6: 'Wasserstoff',
  7: 'Pumpspeicher',
  8: 'Haus',
  9: 'Fabrik',
  10: 'Auto',
  11: 'Umspannwerk'
};

function getAvailableIds(map) {
  return Object.keys(map)
    .map(k => Number(k))
    .filter(n => Number.isFinite(n))
    .sort((a,b) => a - b);
}

function pickMostRecentId(map, ids) {
  if (!ids.length) return null;
  return ids.slice().sort((a,b) => {
    const tb = (map[b]?.timestamp || 0);
    const ta = (map[a]?.timestamp || 0);
    return tb - ta; // neueste zuerst
  })[0];
}

if (msg.payload && msg.payload.init === true) {
  const availableIds = getAvailableIds(tableMap);

  // ID bestimmen (Prio: msg → lastSel → mostRecent)
  const reqId = Number(msg.payload.id);
  let id = Number.isFinite(reqId) ? reqId 
        : Number.isFinite(Number(lastSelId)) ? Number(lastSelId) 
        : pickMostRecentId(tableMap, availableIds);

  const reqType   = (typeof msg.payload.type === 'string' && msg.payload.type)   || 'Verbrauch';
  const reqSeason = (typeof msg.payload.season === 'string' && msg.payload.season) || 'Frühling';

  // Zuletzt genutztes Preset/Season für ID+Type (falls vorhanden)
  const remembered     = (Number.isFinite(id) && lastPresetMap[id] && lastPresetMap[id][reqType]) ? lastPresetMap[id][reqType] : null;
