// 1) Grid (x,y) -> lokale Meter (east,north) mit Rotation
const theta = (rotDeg || 0) * Math.PI / 180;
const ex = x * metersPerUnit;
const ny = y * metersPerUnit;
const east = ex * Math.cos(theta) - ny * Math.sin(theta);
const north = ex * Math.sin(theta) + ny * Math.cos(theta);

// 2) Meter -> Grad (nahe an lat0)
const degLatPerM = 1 / 111320; // ~ Meter pro Breitengrad
const degLonPerM = 1 / (111320 * Math.cos(lat0 * Math.PI / 180));

const lat = lat0 + north * degLatPerM;
const lon = lon0 + east * degLonPerM;

