// ---- Sende-Function: ID/Module per MAC aus tableMap nachtragen + random_cord + optionales Follow-up ----

const FOLLOWUP_DELAY_MS = 1000;  // 1s für request_status nach set_status
const BROADCAST_MAC = "FF:FF:FF:FF:FF:FF";
const DEFAULT_DELAY_MS = 250;

// Hilfsfunktionen
function isEmpty(v) {
  return v === undefined || v === null || (typeof v === "string" && v.trim() === "");
}
function normMac(m) {
  return String(m || "").trim().toUpperCase();
}
function pickByMac(macU, preferId) {
  const tableMap = flow.get("tableMap") || {};
  const list = Object.keys(tableMap).map(k => tableMap[k])
    .filter(e => e && normMac(e.mac) === macU);
  if (!list.length) return null;

  // wenn ID bekannt, diese bevorzugen
  if (!isEmpty(preferId)) {
    const exact = list.find(e => String(e.id) === String(preferId));
    if (exact) return exact;
  }

  // sonst "aktuellsten": höchster timestamp, dann kleinste ID
  list.sort((a, b) => {
    const tb = Number(b.timestamp) || 0;
    const ta = Number(a.timestamp) || 0;
    if (tb !== ta) return tb - ta;
    const ib = Number(b.id), ia = Number(a.id);
    if (Number.isFinite(ia) && Number.isFinite(ib)) return ia - ib;
    return 0;
  });
  return list[0];
}
function randIntIncl(min, max) {
  min = Math.ceil(min); max = Math.floor(max);
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

// 0) Payload robust machen (String -> Objekt)
if (typeof msg.payload === "string") {
  try { msg.payload = JSON.parse(msg.payload); }
  catch (e) { node.warn("Payload ist kein valider JSON-String – leite unverändert weiter."); }
}
if (typeof msg.payload !== "object" || msg.payload === null) {
  node.send(msg);
  return;
}

// 1) Command bestimmen
const cmd = String(msg.payload.cmd || "").trim().toLowerCase();

// === A) random_cord: sequenziell Zufallswerte senden, mit ID/module aus tableMap ===
if (cmd === "random_cord") {
  const tableMap = flow.get("tableMap") || {};
  const delayMs = Number.isFinite(Number(msg.payload.delayMs)) ? Number(msg.payload.delayMs) : DEFAULT_DELAY_MS;

  const reqMacU = normMac(msg.payload.mac);
  let targets = [];

  if (reqMacU === BROADCAST_MAC) {
    // alle MACs aus tableMap einsammeln
    const macSet = {};
    for (const k of Object.keys(tableMap)) {
      const m = normMac(tableMap[k]?.mac);
      if (m) macSet[m] = true;
    }
    targets = Object.keys(macSet);
    if (!targets.length) {
      node.status({ fill: "yellow", shape: "ring", text: "random_cord: keine MACs in tableMap" });
      return;
    }
  } else {
    if (!reqMacU) {
      node.status({ fill: "yellow", shape: "ring", text: "random_cord: keine MAC angegeben" });
      return;
    }
    targets = [reqMacU];
  }

  let i = 0;
  const total = targets.length;

  function sendNext() {
    if (i >= total) {
      node.status({ fill: "green", shape: "dot", text: `random_cord: ${total} gesendet` });
      return;
    }

    const macU = targets[i++];
    const picked = pickByMac(macU, msg.payload.id);

    if (!picked) {
      node.warn(`random_cord: MAC nicht in tableMap gefunden: ${macU}`);
      return setTimeout(sendNext, delayMs);
    }

    const rx = randIntIncl(-90, 90);
    const ry = randIntIncl(-90, 90);

    const out = {
      payload: {
        mac: macU,
        id: picked.id,        // vorhandene ID übernehmen (0 bleibt 0)
        timestamp: null,
        module: picked.module,    // vorhandenes module übernehmen
        consumption: null,
        generation: null,
        storage: null,
        x: rx,
        y: ry,
        error: null,
        cmd: "set_status",
        mode: ""
      }
    };

    node.send(out);
    node.status({ fill: "blue", shape: "dot", text: `random_cord: ${macU} -> x:${rx} y:${ry}` });

    setTimeout(sendNext, delayMs);
  }

  // Start der Sequenz
  sendNext();
  return; // random_cord original NICHT durchreichen
}

// === B) andere Kommandos (außer request_status): ID/module ggf. aus tableMap ergänzen ===
if (cmd !== "request_status") {
  const macU = normMac(msg.payload.mac);
  const idEmpty = isEmpty(msg.payload.id);
  const moduleEmpty = isEmpty(msg.payload.module);

  if (macU && (idEmpty || moduleEmpty)) {
    const pick = pickByMac(macU, msg.payload.id);
    if (pick) {
      if (idEmpty) msg.payload.id = pick.id;
      if (moduleEmpty) msg.payload.module = pick.module;
      msg.payload.mac = macU; // normalisiert
      node.status({ fill: "blue", shape: "dot", text: `ergänzt: id=${msg.payload.id}, module=${msg.payload.module}` });
    } else {
      node.status({ fill: "yellow", shape: "ring", text: "MAC nicht in tableMap gefunden – keine Ergänzung" });
    }
  }
}

// 2) Original (ggf. angereichert) SOFORT weiterleiten
node.send(msg);

// 3) Optionales Follow-up: bei set_status -> nach 1s request_status mit gleicher mac & id
if (cmd === "set_status") {
  const mac2 = normMac(msg.payload.mac);
  const id2 = isEmpty(msg.payload.id) ? "" : String(msg.payload.id);

  const delayedMsg = {
    payload: {
