    }
  };

  node.status({ fill: "green", shape: "dot", text: "set_status -> request_status in 1s" });
  setTimeout(() => {
    try {
      node.send(delayedMsg);
      node.status({ fill: "green", shape: "dot", text: "request_status gesendet" });
    } catch (err) {
      node.error("Fehler beim Senden der request_status: " + err.message, delayedMsg);
    }
  }, FOLLOWUP_DELAY_MS);
}

return;

